namespace moon {
class WorkspacePresetRows final:public ui::Widget {
 const PixelFont& font_;const Skin& skin_;const Skin& icons_;PixelScrollBar* bar_;std::vector<WorkspacePreset> rows_;std::vector<PixelButton*> loads_,deletes_;int scroll_=0;std::string active_;
 void layoutRows(){const auto r=bounds();const int step=(textControlHeight+UiSpacing::related)*uiScale,total=int(rows_.size())*step;scroll_=std::clamp(scroll_,0,std::max(0,total-r.h));bar_->setVisible(total>r.h);const int width=r.w-(bar_->isVisible()?9*uiScale:0);if(bar_->isVisible()){bar_->setBounds({r.x2()-7*uiScale,r.y,7*uiScale,r.h});bar_->configure(total,r.h,scroll_);}for(std::size_t i=0;i<loads_.size();++i){const int y=r.y+int(i)*step-scroll_;const bool visible=i<rows_.size()&&y>=r.y&&y+textControlHeight*uiScale<=r.y2();loads_[i]->setVisible(visible);deletes_[i]->setVisible(visible&&!rows_[i].builtIn);if(!visible)continue;loads_[i]->setBounds({r.x,y,width-(rows_[i].builtIn?0:(UiSpacing::iconSize+UiSpacing::related)*uiScale),textControlHeight*uiScale});deletes_[i]->setBounds({r.x+width-UiSpacing::iconSize*uiScale,y+(textControlHeight-UiSpacing::iconSize)*uiScale/2,UiSpacing::iconSize*uiScale,UiSpacing::iconSize*uiScale});}}
public:
 std::function<void(WorkspacePreset)> load,remove;
 WorkspacePresetRows(const PixelFont& font,const Skin& skin,const Skin& icons):ui::Widget(ui::kGenericWidget),font_(font),skin_(skin),icons_(icons){setTransparent(true);bar_=new PixelScrollBar(skin,true);addChild(bar_);bar_->changed=[this](int value){scroll_=value;layoutRows();invalidate();};}
 void setRows(std::vector<WorkspacePreset> rows,std::string active){rows_=std::move(rows);active_=std::move(active);while(loads_.size()<rows_.size()){const auto i=loads_.size();auto b=new PixelButton(font_,skin_,U"",[this,i]{if(i<rows_.size()&&load){auto value=rows_[i];load(std::move(value));}});b->iconSkin=&icons_;b->icon="workspace";b->iconWithCaption=true;addChild(b);loads_.push_back(b);auto d=new PixelButton(font_,skin_,U"",[this,i]{if(i<rows_.size()&&remove){auto value=rows_[i];remove(std::move(value));}});d->iconSkin=&icons_;d->icon="delete";d->skinStyle="icon_button";addChild(d);deletes_.push_back(d);}for(std::size_t i=0;i<rows_.size();++i){loads_[i]->caption=unicodeText(rows_[i].name)+(rows_[i].builtIn?U"（内置）":U"");loads_[i]->active=rows_[i].id==active_;}layoutRows();invalidate();}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());layoutRows();}
 bool onProcessMessage(ui::Message* msg)override{if(msg->type()==ui::kMouseWheelMessage){scroll_+=static_cast<ui::MouseMessage*>(msg)->wheelDelta().y*(textControlHeight+UiSpacing::related)*uiScale*3;layoutRows();invalidate();return true;}return ui::Widget::onProcessMessage(msg);}
 void onPaint(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale paint(g);skin_.draw(g,"panel_content",uiLogical(clientBounds()));}
 void smokeLoad(std::size_t i){loads_.at(i)->Click();}void smokeDelete(std::size_t i){deletes_.at(i)->Click();}
};
class WorkspacePresetSaveDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;PixelEntry* name_;PixelButton *save_,*cancel_,*close_;std::u32string error_;std::function<std::u32string(const std::string&)> saveAction_;
 void submit(){error_=saveAction_(name_->text());if(error_.empty())closeWindow(nullptr);else invalidate();}
public:
 WorkspacePresetSaveDialog(const PixelFont& font,const Skin& skin,const Skin& icons,std::function<std::u32string(const std::string&)> save):PixelDialog(skin,"",ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow),font_(font),skin_(skin),saveAction_(std::move(save)){setAutoRemap(false);setWantFocus(true);name_=new PixelEntry(font,skin);name_->accept=[this]{submit();};name_->cancel=[this]{closeWindow(nullptr);};addChild(name_);save_=new PixelButton(font,skin,U"保存",[this]{submit();});cancel_=new PixelButton(font,skin,U"取消",[this]{closeWindow(nullptr);});close_=new PixelButton(font,skin,U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";for(auto w:{save_,cancel_,close_})addChild(w);}
 gfx::Size minimumDialogSize(int)const override{return {260*uiScale,DialogLayout::fit(DialogLayout::field()+textControlHeight+UiSpacing::related+UiSpacing::labelHeight)*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();name_->setBounds({r.x+6*uiScale,r.y+DialogLayout::field()*uiScale,r.w-12*uiScale,textControlHeight*uiScale});save_->setBounds({r.x2()-60*uiScale,r.y+DialogLayout::footer(r.h/uiScale)*uiScale,54*uiScale,textControlHeight*uiScale});cancel_->setBounds({save_->bounds().x-56*uiScale,save_->bounds().y,54*uiScale,textControlHeight*uiScale});layoutHeaderButton(close_);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale paint(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"保存为新工作区");font_.draw(g,U"工作区名称",r.x+6,r.y+DialogLayout::label(),skin_["text"]);g.saveClip();g.clipRect(DialogLayout::body(r));font_.draw(g,error_,r.x+6,r.y+DialogLayout::field()+textControlHeight+UiSpacing::related,skin_["text"]);g.restoreClip();}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kKeyDownMessage&&static_cast<ui::KeyMessage*>(msg)->scancode()==ui::kKeyEsc){closeWindow(nullptr);return true;}return PixelPopupWindow::onProcessMessage(msg);}
 void focusName(){name_->requestFocus();}void smoke(const std::string& name,bool save){name_->setText(name);if(save)save_->Click();else cancel_->Click();}bool hasError()const{return !error_.empty();}
};
class WorkspacePresetDeleteDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;std::u32string message_;PixelButton *remove_,*cancel_,*close_;bool accepted_=false;
 std::vector<std::u32string> lines(int width)const{std::vector<std::u32string> out;std::u32string row;for(auto c:message_){if(!row.empty()&&font_.measure(row+c)>width){out.push_back(row);row.clear();}row+=c;}out.push_back(row);return out;}
public:
 WorkspacePresetDeleteDialog(const PixelFont& font,const Skin& skin,const Skin& icons,const std::string& name):PixelDialog(skin,""),font_(font),skin_(skin),message_(U"删除“"+unicodeText(name)+U"”？"){setAutoRemap(false);setWantFocus(true);remove_=new PixelButton(font,skin,U"删除",[this]{accepted_=true;closeWindow(nullptr);});cancel_=new PixelButton(font,skin,U"取消",[this]{closeWindow(nullptr);});close_=new PixelButton(font,skin,U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";for(auto w:{remove_,cancel_,close_})addChild(w);}
 bool accepted()const{return accepted_;}gfx::Size minimumDialogSize(int width)const override{return {300*uiScale,DialogLayout::fit(DialogLayout::bodyTop+int(lines(std::max(300,width/uiScale)-12).size())*12+UiSpacing::group+24)*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();remove_->setBounds({r.x2()-60*uiScale,r.y+DialogLayout::footer(r.h/uiScale)*uiScale,54*uiScale,textControlHeight*uiScale});cancel_->setBounds({remove_->bounds().x-56*uiScale,remove_->bounds().y,54*uiScale,textControlHeight*uiScale});layoutHeaderButton(close_);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale paint(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"删除工作区");int y=r.y+DialogLayout::bodyTop;for(const auto& row:lines(r.w-12)){font_.draw(g,row,r.x+6,y,skin_["text"]);y+=12;}font_.draw(g,U"仅删除窗口布局文件，",r.x+6,y+UiSpacing::group,skin_["text"]);font_.draw(g,U"工程和图片不受影响。",r.x+6,y+UiSpacing::group+12,skin_["text"]);}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kKeyDownMessage&&static_cast<ui::KeyMessage*>(msg)->scancode()==ui::kKeyEsc){closeWindow(nullptr);return true;}return PixelPopupWindow::onProcessMessage(msg);}void smoke(bool yes){if(yes)remove_->Click();else cancel_->Click();}
};
class WorkspacePresetManagerDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;WorkspacePresetRows* rows_;PixelButton *create_,*folder_,*close_;bool createNext_=false;std::u32string error_;std::function<std::vector<WorkspacePreset>()> listing_;std::function<std::string()> active_;
 void reload(){try{rows_->setRows(listing_(),active_());}catch(const std::exception& e){error_=unicodeText(e.what());}invalidate();}
public:
 WorkspacePresetManagerDialog(const PixelFont& font,const Skin& skin,const Skin& icons,std::function<std::vector<WorkspacePreset>()> listing,std::function<std::string()> active,std::function<std::u32string(const std::string&)> load,std::function<std::u32string(const std::string&)> remove,std::function<void()> folder):PixelDialog(skin,"",ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow),font_(font),skin_(skin),listing_(std::move(listing)),active_(std::move(active)){setAutoRemap(false);setWantFocus(true);rows_=new WorkspacePresetRows(font,skin,icons);addChild(rows_);rows_->load=[this,load](WorkspacePreset value){error_=load(value.id);reload();};rows_->remove=[this,remove](WorkspacePreset value){error_=remove(value.id);reload();};create_=new PixelButton(font,skin,U"新建工作区",[this]{createNext_=true;closeWindow(nullptr);});folder_=new PixelButton(font,skin,U"打开工作区文件夹",[this,folder]{try{folder();}catch(const std::exception& e){error_=unicodeText(e.what());invalidate();}});folder_->iconSkin=&icons;folder_->icon="folderOpen";folder_->iconWithCaption=true;create_->iconSkin=&icons;create_->icon="plus";create_->iconWithCaption=true;close_=new PixelButton(font,skin,U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";for(auto w:{create_,folder_,close_})addChild(w);reload();}
 bool createNext()const{return createNext_;}gfx::Size minimumDialogSize(int)const override{return {340*uiScale,220*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();rows_->setBounds({r.x+6*uiScale,r.y+DialogLayout::bodyTop*uiScale,r.w-12*uiScale,std::max(1,r.h-(DialogLayout::bodyTop+6+textControlHeight+UiSpacing::group+12)*uiScale)});folder_->setBounds({r.x+6*uiScale,r.y+DialogLayout::footer(r.h/uiScale)*uiScale,164*uiScale,textControlHeight*uiScale});create_->setBounds({r.x2()-116*uiScale,folder_->bounds().y,110*uiScale,textControlHeight*uiScale});layoutHeaderButton(close_);}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale paint(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,U"工作区管理");g.saveClip();g.clipRect(DialogLayout::body(r));font_.draw(g,error_,r.x+6,r.y+DialogLayout::footer(r.h)-12,skin_["text"]);g.restoreClip();}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kKeyDownMessage&&static_cast<ui::KeyMessage*>(msg)->scancode()==ui::kKeyEsc){closeWindow(nullptr);return true;}return PixelPopupWindow::onProcessMessage(msg);}void smokeLoad(std::size_t i){rows_->smokeLoad(i);}void smokeDelete(std::size_t i){rows_->smokeDelete(i);}void smokeClose(){close_->Click();}
};
}
